(1, 'news-1', 'Seminar on Anti Drug awareness', 'news', '2026-11-12', 'The University of Swat has reaffirmed its commitment to creating anti-drug awareness among students.Swat (Campus News): The Office of the Provost, University of Swat, in collaboration with District Youth Affairs, Swat, held an anti-drug awareness seminar at the Theater Hall on Wednesday to reaffirm its steadfast dedication to fostering a safe, healthy, and intellectually stimulating …', 'https://uswat.edu.pk/2026/11/seminar-on-anti-drug-awareness/', NULL, NULL, 1),
(2, 'news-2', 'University of Swat Joins Hands with NCHD for “Each One Teach One”', 'news', '2026-11-12', 'University of Swat Joins Hands with NCHD for “Each One Teach One” Prime Minister’s Youth ProgrammeSwat (Campus News): The University of Swat and National Commission for Human Development (NCHD) have signed a Memorandum of Understanding (MoU) today to launch the “Each One Teach One” literacy initiative.Under this program, BS students of the University will identify …', 'https://uswat.edu.pk/2026/11/university-of-swat-joins-hands-with-nchd-for-each-one-teach-one/', NULL, NULL, 1),
(3, 'news-3', 'One-Day Seminar on “Robot Trader: Algorithmic Trading for a Smarter Financial Future”', 'news', '2026-11-12', 'University of Swat Organizes One-Day Seminar on “Robot Trader: Algorithmic Trading for a Smarter Financial Future”Swat (Campus News): The Department of Management and Commerce, University of Swat, organized a highly insightful One-Day Seminar on “Robot Trader: Algorithmic Trading for a Smarter Financial Future” on Wednesday at the Main Theatre Hall, University of Swat. The event …', 'https://uswat.edu.pk/2026/11/one-day-seminar-on-robot-trader-algorithmic-trading-for-a-smarter-financial-future/', NULL, NULL, 1),
(4, 'news-4', 'Prof. Dr. Luca Maria Olivieri (Sitara-i-Imtiaz), Director of the Italian Archaeological Mission to Pakistan held a meeting with Vice Chancellor', 'news', '2026-11-11', 'Prof. Dr. Luca Maria Olivieri (Sitara-i-Imtiaz), Director of the Italian Archaeological Mission to Pakistan (IAMP), based at Saidu Sharif, Swat, visited the University of Swat and held a meeting with Prof. Dr. Husnul Amin, Vice Chancellor, University of Swat. During the meeting, Prof. Olivieri congratulated the Vice Chancellor on assuming charge of the University and …', 'https://uswat.edu.pk/2026/11/prof-dr-luca-maria-olivieri-sitara-i-imtiaz-director-of-the-italian-archaeological-mission-to-pakistan-held-a-meeting-with-vice-chancellor/', NULL, NULL, 1),
