(29, 'announcement-9', 'SWAT DEVELOPMENT FORUM (SDF)', 'announcement', '2026-10-20', 'SWAT DEVELOPMENT FORUM (SDF) – a multidisciplinary research, policy and community-engagement initiative which will be dedicated to debating the socioeconomic development, sustainable peace and environmental resilience of Swat and the wider Malakand region.We’re fully cognizant to the interconnected challenges of post-conflict recovery, youth unemployment, climate change, rapid urbanization, economic vulnerability and social exclusion in Swat …', 'https://uswat.edu.pk/2026/10/swat-development-forum-sdf/', NULL, NULL, 1),
(30, 'announcement-10', '(ORIC) PRESENTS PERFORMANCE REPORT TO VICE CHANCELLOR', 'announcement', '2026-10-15', 'OFFICE OF RESEARCH, INNOVATION AND COMMERCIALIZATION (ORIC), UNIVERSITY OF SWAT PRESENTS PERFORMANCE REPORT TO VICE CHANCELLORThe Office of Research, Innovation, and Commercialization (ORIC), University of Swat, presented a detailed performance and progress report in a meeting held here on Wednesday.The meeting was chaired by the Vice Chancellor, Prof. Dr. Husnul Amin, in which Prof. Dr. …', 'https://uswat.edu.pk/2026/10/oric-presents-performance-report-to-vice-chancellor/', NULL, NULL, 1),
(31, 'announcement-11', 'Vice Chancellor, visits the women’s campus with the goal of transforming it into a center of excellence for female education.', 'announcement', '2026-10-15', 'The Vice Chancellor, University of Swat, visits the women’s campus with the goal of transforming it into a center of excellence for female education.The Vice Chancellor, University of Swat, Prof. Dr. Husnul Amin visited the Women’s Campus of the University. He was accompanied by Registrar, Dr. Arshad Ali Khan, and Provost, Dr. Muhammad Imad KhanDr. …', 'https://uswat.edu.pk/2026/10/vice-chancellor-visits-the-womens-campus-with-the-goal-of-transforming-it-into-a-center-of-excellence-for-female-education/', NULL, NULL, 1),
(32, 'announcement-12', 'Chairman of HEC Meets Vice Chancellor', 'announcement', '2026-10-14', 'Chairman of HEC Meets Vice Chancellor, University of SwatProfessor Dr. Niaz Ahmad Akhtar, Chairman HEC, Islamabad, received Professor Dr. Husnul Amin, Vice Chancellor, University of Swat at his office. The Chairman congratulated Dr. Husnul Amin on his appointment as Vice Chancellor. Prof. Amin thanked the Chairman for his warm wishes. During the meeting, the Vice …', 'https://uswat.edu.pk/2026/10/chairman-of-hec-meets-vice-chancellor/', NULL, NULL, 1),
(33, 'event-1', 'Seminar on Anti Drug awareness', 'event', '2026-11-12', 'The University of Swat has reaffirmed its commitment to creating anti-drug awareness among students.Swat (Campus News): The Office of the Provost, University of Swat, in collaboration with District Youth Affairs, Swat, held an anti-drug awareness seminar at the Theater Hall on Wednesday to reaffirm its steadfast dedication to fostering a safe, healthy, and intellectually stimulating …', 'https://uswat.edu.pk/2026/11/seminar-on-anti-drug-awareness/', NULL, NULL, 1),
(34, 'event-2', 'University of Swat Joins Hands with NCHD for “Each One Teach One”', 'event', '2026-11-12', 'University of Swat Joins Hands with NCHD for “Each One Teach One” Prime Minister’s Youth ProgrammeSwat (Campus News): The University of Swat and National Commission for Human Development (NCHD) have signed a Memorandum of Understanding (MoU) today to launch the “Each One Teach One” literacy initiative.Under this program, BS students of the University will identify …', 'https://uswat.edu.pk/2026/11/university-of-swat-joins-hands-with-nchd-for-each-one-teach-one/', NULL, NULL, 1),
(35, 'event-3', 'One-Day Seminar on “Robot Trader: Algorithmic Trading for a Smarter Financial Future”', 'event', '2026-11-12', 'University of Swat Organizes One-Day Seminar on “Robot Trader: Algorithmic Trading for a Smarter Financial Future”Swat (Campus News): The Department of Management and Commerce, University of Swat, organized a highly insightful One-Day Seminar on “Robot Trader: Algorithmic Trading for a Smarter Financial Future” on Wednesday at the Main Theatre Hall, University of Swat. The event …', 'https://uswat.edu.pk/2026/11/one-day-seminar-on-robot-trader-algorithmic-trading-for-a-smarter-financial-future/', NULL, NULL, 1),
(36, 'event-4', 'University of Swat and Sri Lankan NIIBS Sign Landmark MoU to Strengthen Research on Gandhara Civilization', 'event', '2026-11-06', 'University of Swat and Sri Lankan NIIBS Sign Landmark MoU to Strengthen Research on Gandhara CivilizationSWAT (Campus Bulletin): The University of Swat on Thursday signed an important Memorandum of Understanding (MoU) with the Nagananda International Institute for Buddhist Studies (NIIBS), Sri Lanka, aimed at fostering student and faculty exchange and promoting joint research, particularly on …', 'https://uswat.edu.pk/2026/11/university-of-swat-and-sri-lankan-niibs-sign-landmark-mou-to-strengthen-research-on-gandhara-civilization/', NULL, NULL, 1),
(37, 'event-5', 'Awareness Drive on Cervical Cancer Preventions', 'event', '2026-11-05', 'University of Swat Leads Awareness Drive on Cervical Cancer Preventions.Swat (Campus Bulletin)The University of Swat organized an awareness seminar on “Students Leading the Fight Against Cervical Cancer: Empowering Faculty and Students to Champion Cervical Cancer Prevention Through Vaccination” at the Theatre Hall, University of Swat, on Tuesday.More than 200 female students and faculty members from …', 'https://uswat.edu.pk/2026/11/awareness-drive-on-cervical-cancer-preventions/', NULL, NULL, 1),
(38, 'event-6', 'Kashmir Black Day (Youm-e-Siah)', 'event', '2026-10-27', 'The University of Swat observed Kashmir Black Day (Youm-e-Siah) today to condemn the illegal occupation of Jammu and Kashmir by India on 27th October 1947 and to express unwavering solidarity with the people of Indian Illegally Occupied Jammu and Kashmir (IIOJK).In this connection, a seminar was organized by the Office of the Provost, University of …', 'https://uswat.edu.pk/2026/10/kashmir-black-day-youm-e-siah/', NULL, NULL, 1),
(39, 'event-7', 'Expansion of Hunerkada Institute at University of Swat', 'event', '2026-10-26', 'Vice Chancellor, University of Swat discusses expansion of Hunerkada Institute at University of SwatCharbagh (Campus Bulletin) The Vice Chancellor, University of Swat, Prof. Dr. Husnul Amin, held a highly productive meeting with renowned artist and former Federal Minister, Syed Jamal Shah, and Madam Amna Shah regarding the future expansion of Hunerkada Institute at the University …', 'https://uswat.edu.pk/2026/10/expansion-of-hunerkada-institute-at-university-of-swat/', NULL, NULL, 1),
(40, 'event-8', 'The Role of Human Psychology in Shaping Manners and Personality', 'event', '2026-10-23', 'NEWS REPORTBy: Arshad Ali Khan Department of Media and communication Study University of Swat – A seminar titled “The Role of Human Psychology in Shaping Manners and Personality” was organized today on 22nd October, 2026 (Thursday) at 11:30 AM at the Theatre Hall, University of Swat.The seminar was organized by the Young Peace and Development …', 'https://uswat.edu.pk/2026/10/the-role-of-human-psychology-in-shaping-manners-and-personality/', NULL, NULL, 1),
(41, 'event-9', 'Department of Geology, conducted a seminar titled “Mud Logging: From Drilling to Geological Interpretation.”', 'event', '2026-10-23', 'Department of Geology, University of Swat, successfully conducted a seminar titled “Mud Logging: From Drilling to Geological Interpretation.”The resource person, Mr. Kifayat Ullah, Senior Drilling Fluids Engineer at Halliburton Pakistan, shared valuable industry insights and practical knowledge with students.The Department of Geology extends its heartfelt gratitude to Mr. Kifayat Ullah for his valuable contribution and …', 'https://uswat.edu.pk/2026/10/department-of-geology-conducted-a-seminar-titled-mud-logging-from-drilling-to-geological-interpretation/', NULL, NULL, 1),
(42, 'event-10', 'One-Day Seminar on Environmental Research, Policy and Sustainable Ecosystems', 'event', '2026-10-01', 'Department of Chemistry Organizes One-Day Seminar on Environmental Research, Policy and Sustainable EcosystemsDepartment of Chemistry, University of Swat, organized a one-day seminar on the theme “The Gap Between Environmental Research, Interdisciplinary Education, Policy and Practice for a Sustainable Ecosystem.” The seminar provided an academic platform for faculty members and students to discuss contemporary environmental challenges …', 'https://uswat.edu.pk/2026/10/one-day-seminar-on-environmental-research-policy-and-sustainable-ecosystems/', NULL, NULL, 1),
(43, 'event-11', 'Seminar on Character in the Digital Age', 'event', '2026-09-30', 'Character Building Society, University of Swat and Psychology Students Society jointly organized a seminar on Character in the Digital Age:The influence of Social Media. Dr. Faheem and Ms. Palwasha Rahim were organizers of the event.Students from Main Campus as well as Women Campus actively participated in the session.The resource persons were Dr. Yahya Khan, Dr. …', 'https://uswat.edu.pk/2026/09/seminar-on-character-in-the-digital-age/', NULL, NULL, 1),
(44, 'event-12', 'Digital Climate Health Symposium on Vector-Borne Diseases', 'event', '2026-09-26', 'Department of Computer and Software Technology, University of Swat, in collaboration with the Environmental Protection Society (EPS), supported by IRC Pakistan and the Sanofi, successfully organised successfully organized a one-day “Digital Climate Health Symposium on Vector-Borne Diseases”.The event was graced by Honourable Vice Chancellor, Prof. Dr. Muhammad Qasim, as the Chief Guest. The symposium focused …', 'https://uswat.edu.pk/2026/09/digital-climate-health-symposium-on-vector-borne-diseases/', NULL, NULL, 1),
