-- =====================================================================
-- University of Swat - website seed data (MySQL 8)
--
-- SOURCE: https://uswat.edu.pk/  (University of Swat, Khyber Pakhtunkhwa,
--         Pakistan). The static directory data (campuses, faculties,
--         departments, degree types, programmes, pages) is transcribed from
--         the institution's own published pages; the editorial content
--         (news, announcements, events, tenders, jobs) is taken verbatim from
--         the university WordPress REST API.
--
-- RUN ORDER:
--   1) mysql -u root -p < database/schema.sql
--   2) mysql -u root -p < database/seed.sql
--
-- The file truncates all ten tables (in dependency order) and then
-- re-inserts every row with explicit primary keys.
-- =====================================================================

SET NAMES utf8mb4;
USE uswat;
SET FOREIGN_KEY_CHECKS = 0;

TRUNCATE TABLE program_keywords;
TRUNCATE TABLE programs;
TRUNCATE TABLE keywords;
TRUNCATE TABLE departments;
TRUNCATE TABLE faculties;
TRUNCATE TABLE campuses;
TRUNCATE TABLE degree_types;
TRUNCATE TABLE content_items;
TRUNCATE TABLE stats;
TRUNCATE TABLE pages;

SET FOREIGN_KEY_CHECKS = 1;

